<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import type{FormInstance,FormRules,UploadFile}from'element-plus';import{ElMessage}from'element-plus';import{Edit,Message,Phone,User}from'@element-plus/icons-vue';import{getCurrentUser,updateOwnMessage}from'@/api/user';import{uploadAvatar}from'@/api/upload';import{useUserStore}from'@/stores/user';
const store=useUserStore(),formRef=ref<FormInstance>(),editing=ref(false),saving=ref(false),avatarFile=ref<File>(),password=ref('');const form=reactive<any>({id:0,username:'',email:'',telephone:'',avatarPath:''});const rules:FormRules={username:[{required:true,message:'请输入用户名',trigger:'blur'}],email:[{required:true,message:'请输入邮箱',trigger:'blur'},{type:'email',message:'邮箱格式不正确',trigger:'blur'}],telephone:[{required:true,message:'请输入手机号',trigger:'blur'}]};const assign=(u:any)=>Object.assign(form,{id:u?.id||0,username:u?.username||'',email:u?.email||'',telephone:u?.telephone||u?.phone||'',avatarPath:u?.avatarPath||u?.avatar_path||''});onMounted(async()=>{if(store.user)assign(store.user);else try{const r:any=await getCurrentUser();assign(r?.data)}catch{}});const choose=(file:UploadFile)=>{if(file.raw){avatarFile.value=file.raw;form.avatarPath=URL.createObjectURL(file.raw)}};const save=async()=>{if(!editing.value){editing.value=true;return}if(!formRef.value||!(await formRef.value.validate().catch(()=>false)))return;saving.value=true;try{let avatar=form.avatarPath;if(avatarFile.value){const u:any=await uploadAvatar(avatarFile.value);avatar=u?.data||u?.url||avatar}await updateOwnMessage(form.id,form.username,password.value,avatar,form.email,form.telephone,'student');const next:any={...(store.user||{}),...form,avatarPath:avatar};store.saveUser(next);form.avatarPath=avatar;editing.value=false;password.value='';ElMessage.success('个人资料已保存')}catch{ElMessage.error('保存失败，请稍后重试')}finally{saving.value=false}}
</script>
<template><div class="profile-page"><header class="page-header"><p>MY ACCOUNT</p><h1>个人资料</h1><span>管理账户信息与联系方式</span></header><main class="profile-main"><section class="profile-card"><aside><el-upload :show-file-list="false" :auto-upload="false" accept="image/*" :on-change="choose"><el-avatar :size="96" :src="form.avatarPath">{{form.username?.slice(0,1)}}</el-avatar><span class="avatar-edit"><Edit/></span></el-upload><h2>{{form.username||'校园用户'}}</h2><p>{{form.email||'尚未填写邮箱'}}</p><div class="safe"><i/>账户状态正常</div></aside><div class="form-area"><div class="form-title"><div><h2>基本信息</h2><p>保持信息准确，便于接收服务通知</p></div><el-button :type="editing?'primary':'default'" :loading="saving" @click="save">{{editing?'保存修改':'编辑资料'}}</el-button></div><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" :prefix-icon="User" :disabled="!editing"/></el-form-item><el-form-item label="电子邮箱" prop="email"><el-input v-model="form.email" :prefix-icon="Message" :disabled="!editing"/></el-form-item><el-form-item label="手机号码" prop="telephone"><el-input v-model="form.telephone" :prefix-icon="Phone" :disabled="!editing"/></el-form-item><el-form-item label="新密码（可选）"><el-input v-model="password" type="password" show-password placeholder="留空则不修改密码" :disabled="!editing"/></el-form-item></el-form></div></section></main></div></template>
<style scoped>.profile-page{min-height:calc(100vh - 72px);padding-bottom:40px;background:var(--surface-muted)}.page-header p,.page-header h1,.page-header span{margin:0}.page-header p{color:var(--brand);font-size:11px;font-weight:800;letter-spacing:.11em}.page-header h1{margin:7px 0 9px}.page-header span{color:var(--text-secondary)}.profile-card{display:grid;grid-template-columns:280px 1fr;padding:0!important;overflow:hidden}.profile-card aside{padding:38px;text-align:center;background:#f0f5f1;border-right:1px solid var(--border-color)}.profile-card aside :deep(.el-upload){position:relative}.avatar-edit{position:absolute;right:-3px;bottom:3px;width:30px;height:30px;display:grid;place-items:center;color:#fff;background:var(--brand);border:3px solid #f0f5f1;border-radius:50%}.avatar-edit :deep(svg){width:13px}.profile-card aside h2{margin:18px 0 5px;font-size:20px}.profile-card aside p{margin:0;color:var(--text-muted);font-size:12px}.safe{width:fit-content;margin:24px auto 0;padding:7px 10px;color:var(--success);background:#e1f1e7;border-radius:99px;font-size:10px;font-weight:700}.safe i{display:inline-block;width:6px;height:6px;margin-right:5px;background:currentColor;border-radius:50%}.form-area{padding:36px}.form-title{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:27px}.form-title h2,.form-title p{margin:0}.form-title h2{font-size:21px}.form-title p{margin-top:5px;color:var(--text-muted);font-size:11px}.form-area :deep(.el-form){max-width:580px}@media(max-width:720px){.profile-card{grid-template-columns:1fr}.profile-card aside{border-right:0;border-bottom:1px solid var(--border-color)}.form-area{padding:24px 18px}}</style>
